                .current_dir(&dir)
                .output()
                .unwrap()
                .status
                .success());
        };
        git(&["init", "-q"]);
        std::fs::write(dir.join("kept.txt"), "one\\n").unwrap();
        std::fs::write(dir.join("other.txt"), "a\\n").unwrap();
